import{_ as t,o as a,c as i,ao as s}from"./chunks/framework.Dz-3nxMo.js";const k=JSON.parse('{"title":"Instrument Formats","description":"","frontmatter":{},"headers":[],"relativePath":"developers/formats.md","filePath":"developers/formats.md","lastUpdated":null}'),n={name:"developers/formats.md"};function l(r,e,d,o,h,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="Instrument-Formats" tabindex="-1">Instrument Formats <a class="header-anchor" href="#Instrument-Formats" aria-label="Permalink to &quot;Instrument Formats {#Instrument-Formats}&quot;">​</a></h1><p>Timekeepers reads three instrument formats natively. It also writes the three formats. Each format has the same three functions:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Format</th><th style="text-align:left;">Run reader</th><th style="text-align:left;"><code>TimeArray</code> reader</th><th style="text-align:left;">Writer</th></tr></thead><tbody><tr><td style="text-align:left;">LEMI-424</td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.read_lemi424"><code>read_lemi424</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.load_lemi424"><code>load_lemi424</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.write_lemi424"><code>write_lemi424</code></a></td></tr><tr><td style="text-align:left;">GEOMAG-02</td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.read_geomag"><code>read_geomag</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.load_geomag"><code>load_geomag</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.write_geomag"><code>write_geomag</code></a></td></tr><tr><td style="text-align:left;">Metronix ADU</td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.read_metronix"><code>read_metronix</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.load_metronix"><code>load_metronix</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.write_metronix"><code>write_metronix</code></a></td></tr></tbody></table><p><a href="/Timekeepers.jl/dev/api#Timekeepers.read_timekeeper"><code>read_timekeeper</code></a> and <a href="/Timekeepers.jl/dev/api#Timekeepers.write_timekeeper"><code>write_timekeeper</code></a> operate for the three formats. They select the correct function automatically.</p><h2 id="Component-naming" tabindex="-1">Component naming <a class="header-anchor" href="#Component-naming" aria-label="Permalink to &quot;Component naming {#Component-naming}&quot;">​</a></h2><p>All the formats use one set of channel names. Thus, the other parts of the package (masks, plots and spectra) operate the same for each format:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Component</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Units</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:bx</code>, <code>:by</code>, <code>:bz</code></td><td style="text-align:left;">magnetic field, geographic N / E / down</td><td style="text-align:left;">nT</td></tr><tr><td style="text-align:left;"><code>:e1</code>, <code>:e2</code></td><td style="text-align:left;">electric field, dipole 1 / 2</td><td style="text-align:left;">mV/km</td></tr><tr><td style="text-align:left;"><code>:temperature_e</code>, <code>:temperature_h</code></td><td style="text-align:left;">electronics / sensor temperature</td><td style="text-align:left;">°C</td></tr><tr><td style="text-align:left;"><code>:battery</code></td><td style="text-align:left;">supply voltage</td><td style="text-align:left;">V</td></tr><tr><td style="text-align:left;"><code>:elevation</code></td><td style="text-align:left;">GPS elevation</td><td style="text-align:left;">m</td></tr></tbody></table><p><a href="/Timekeepers.jl/dev/api#Timekeepers.default_components"><code>default_components</code></a> returns the five signal channels in the usual plot order (<code>bx, by, bz, e1, e2</code>). <a href="/Timekeepers.jl/dev/api#Timekeepers.components"><code>components</code></a> returns all the channels in the run, which include the auxiliary channels.</p><h2 id="LEMI-424" tabindex="-1">LEMI-424 <a class="header-anchor" href="#LEMI-424" aria-label="Permalink to &quot;LEMI-424 {#LEMI-424}&quot;">​</a></h2><p>LEMI-424 is a long-period ASCII text format. Each sample has one record, with the fields separated by whitespace. A record has six date and time fields. Then it has the magnetic, electric, temperature, GPS and housekeeping columns. <a href="/Timekeepers.jl/dev/api#Timekeepers.LEMI424_COLUMNS"><code>LEMI424_COLUMNS</code></a> gives the names of the 24 fields in the file order.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Timekeepers</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read_lemi424</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/LEMI090.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ta  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_lemi424</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/LEMI090.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># straight to a TimeArray</span></span></code></pre></div><p>Some real files do not have exactly 24 columns. Some firmware revisions add fields at the end, and some exports remove fields at the end. The reader accepts the two cases. It ignores the extra columns. It returns <code>NaN</code> for each missing column at the end, and does not give an error.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read_lemi424</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/short_record.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">all</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(isnan, run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">channels[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:time_diff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># true when the column was absent</span></span></code></pre></div><p>If you only need the five signal components, give <code>include_aux = false</code>. The reader then does not read the housekeeping channels.</p><p>The writer makes the original layout of 24 fields again. The <code>TimeArray</code> metadata keeps the auxiliary values under <code>:aux_columns</code>. The writer puts each value back in its own position. Thus, a cycle of read and write does not lose data:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ta </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_lemi424</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/LEMI090.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">write_lemi424</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/LEMI090_copy.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ta)</span></span></code></pre></div><p>The two writers accept a <a href="/Timekeepers.jl/dev/api#Timekeepers.TimekeeperRun"><code>TimekeeperRun</code></a> or a <code>TimeArray</code>.</p><h3 id="Generic-LEMI-.xyz-exports" tabindex="-1">Generic LEMI <code>.xyz</code> exports <a class="header-anchor" href="#Generic-LEMI-.xyz-exports" aria-label="Permalink to &quot;Generic LEMI \`.xyz\` exports {#Generic-LEMI-.xyz-exports}&quot;">​</a></h3><p>TKApp also loads and writes LEMI-style exports that have 7 columns (<code>date time Bx By Bz Ex Ey</code>). The file must have the <code>.xyz</code> extension. There is no public reader for these files. Open them with the app or with <a href="/Timekeepers.jl/dev/api#Timekeepers.run_tkapp"><code>run_tkapp</code></a>.</p><h2 id="GEOMAG-02" tabindex="-1">GEOMAG-02 <a class="header-anchor" href="#GEOMAG-02" aria-label="Permalink to &quot;GEOMAG-02 {#GEOMAG-02}&quot;">​</a></h2><p>GEOMAG-02 is an ASCII text format. The file starts with a block of header lines. Each header line starts with <code>;</code>. The header gives the instrument model, the sampling interval and the position of the station. Then the file has one record for each sample, with fractional seconds.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read_geomag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/MS_26_250523000000.TXT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sampling_rate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(run)                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 10.0 for a 0.10 s interval</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">metadata[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:instrument_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># &quot;GEOMAG-02&quot;</span></span></code></pre></div><p>The format detection looks for the <code>GEOMAG</code> token in the header. Thus, <a href="/Timekeepers.jl/dev/api#Timekeepers.read_timekeeper"><code>read_timekeeper</code></a> can tell a GEOMAG file from a LEMI-424 <code>.txt</code> file without help.</p><p>The reader reads the five signal channels. It also reads <code>:temperature_h</code> and <code>:temperature_e</code>. <a href="/Timekeepers.jl/dev/api#Timekeepers.write_geomag"><code>write_geomag</code></a> writes the header block and the data. Thus, the tools that read the input can also read the output.</p><h2 id="Metronix-ADU-ATS" tabindex="-1">Metronix ADU (ATS) <a class="header-anchor" href="#Metronix-ADU-ATS" aria-label="Permalink to &quot;Metronix ADU (ATS) {#Metronix-ADU-ATS}&quot;">​</a></h2><p>A Metronix run is a set of files in a <code>meas_*</code> directory. Each channel has one <code>.ats</code> binary file, and the run has an <code>.xml</code> sidecar. A <code>meas_*</code> directory can hold more than one run, for example a 128 Hz run and 4096 Hz bursts. The run number (<code>R000</code>, <code>R001</code>, …) and the rate in the filenames identify each run.</p><p>The <code>.ats</code> header gives these values:</p><ul><li><p>the number of samples;</p></li><li><p>the sampling rate;</p></li><li><p>the start time, as a Unix timestamp;</p></li><li><p>the LSB scale value;</p></li><li><p>the channel type.</p></li></ul><p>The samples are <code>Int32</code> counts. The reader multiplies them by the LSB value.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read_metronix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/RK137/meas_2025-04-01_07-00-05&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(run)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [:bx, :by, :bz, :e1, :e2]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sampling_rate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(run)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 128.0</span></span></code></pre></div><p><a href="/Timekeepers.jl/dev/api#Timekeepers.METRONIX_CHANNEL_MAP"><code>METRONIX_CHANNEL_MAP</code></a> changes the channel types to component names: <code>Ex → :e1</code>, <code>Ey → :e2</code>, <code>Hx → :bx</code>, <code>Hy → :by</code>, <code>Hz → :bz</code>. The reader does not remove a channel type that it does not know. It keeps that channel under a symbol with the same name.</p><div class="tip custom-block"><p class="custom-block-title">Point at one run</p><p><a href="/Timekeepers.jl/dev/api#Timekeepers.read_metronix"><code>read_metronix</code></a> accepts the <code>.xml</code> of a run, one of its <code>.ats</code> files, or a <code>meas_*</code> directory that holds one run. A directory that holds more than one run is ambiguous, and the error gives a list of the runs. For the site directory above the <code>meas_*</code> directories, use <a href="/Timekeepers.jl/dev/api#Timekeepers.metronix_site_runs"><code>metronix_site_runs</code></a> and the site writers. Refer to <a href="./metronix">Metronix Sites</a>.</p></div><p><a href="/Timekeepers.jl/dev/api#Timekeepers.write_metronix"><code>write_metronix</code></a> writes a measurement directory. It makes the XML sidecar again from the template that the reader used. The path of that template is in <code>run.metadata[:metronix_xml_path]</code>. Thus, the run must come from <a href="/Timekeepers.jl/dev/api#Timekeepers.read_metronix"><code>read_metronix</code></a> before you can write it as Metronix.</p><p>A mask on Metronix data usually means &quot;cut this interval out&quot;. Thus, Metronix has a second writer that cuts the data and does not put blanks in it. Refer to <a href="./metronix">Metronix Sites</a>.</p><h2 id="Metadata-that-the-readers-keep" tabindex="-1">Metadata that the readers keep <a class="header-anchor" href="#Metadata-that-the-readers-keep" aria-label="Permalink to &quot;Metadata that the readers keep {#Metadata-that-the-readers-keep}&quot;">​</a></h2><p>The readers keep the run information that a writer needs. You can find all of it in <code>run.metadata</code>, or in <code>TimeSeries.meta(ta)</code> for a <code>TimeArray</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Present for</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:sample_rate</code></td><td style="text-align:left;">all</td><td style="text-align:left;">samples per second</td></tr><tr><td style="text-align:left;"><code>:start_time</code></td><td style="text-align:left;">all</td><td style="text-align:left;">timestamp of the first sample</td></tr><tr><td style="text-align:left;"><code>:instrument_model</code></td><td style="text-align:left;">GEOMAG, Metronix</td><td style="text-align:left;">instrument identification</td></tr><tr><td style="text-align:left;"><code>:aux_columns</code></td><td style="text-align:left;">LEMI-424, GEOMAG</td><td style="text-align:left;">values of the auxiliary columns, for writes that do not lose data</td></tr><tr><td style="text-align:left;"><code>:site</code>, <code>:n_files</code></td><td style="text-align:left;">site loads</td><td style="text-align:left;">site name and number of runs that were joined</td></tr><tr><td style="text-align:left;"><code>:metronix_xml_path</code></td><td style="text-align:left;">Metronix</td><td style="text-align:left;">XML template that makes the sidecar again</td></tr><tr><td style="text-align:left;"><code>:metronix_prefix</code>, <code>:metronix_run_token</code>, <code>:metronix_freq_token</code></td><td style="text-align:left;">Metronix</td><td style="text-align:left;">filename tokens that the writer keeps</td></tr><tr><td style="text-align:left;"><code>:mask_intervals</code>, <code>:masked_samples</code></td><td style="text-align:left;">after a mask</td><td style="text-align:left;">the intervals that were cut, and the number of samples</td></tr></tbody></table>`,37)])])}const m=t(n,[["render",l]]);export{k as __pageData,m as default};
